àn","description":"Cụm sân bóng đá cỏ nhân tạo ngoài trời gồm các sân 5 người và có thể ghép thành sân 7 người. Mặt cỏ dày, rải hạt cao su đàn hồi giảm chấn động cho khớp gối và cổ chân. Hệ thống thoát nước nhanh chóng giúp sân luôn khô ráo sau mưa.","specs":[{"label":"Quy cách sân","value":"2 sân 5 hoặc ghép thành 1 sân 7"},{"label":"Mặt cỏ","value":"Cỏ nhân tạo chuyên dụng rải hạt cao su"},{"label":"Chiếu sáng","value":"Dàn đèn LED cao áp rõ nét ban đêm"},{"label":"Bao quanh","value":"Lưới chắn bóng cao 6m chắc chắn"}],"amenities":["Ghế ngồi chờ có mái che bên sân","Phòng thay đồ & vệ sinh sạch sẽ","Cho mượn áo bib phân đội & bóng tập","Quầy nước giải khát tiện lợi"],"tags":["Bóng đá phong trào","Giao lưu đội nhóm","Thi đấu giao hữu"],"isVisible":true},{"id":"room-03","name":"Cụm Sân Cầu Lông Thảm Chống Trượt","category":"team-sports","categoryName":"Sân bóng & Vợt","location":"Khu B • Tầng 2","zone":"Khu B","capacity":"16 - 24 người chơi","openHours":"06:00 - 22:00 hàng ngày","priceRate":"Từ 60.000đ - 100.000đ/giờ/sân","badge":"Thảm Chuyên Dụng","badgeColor":"bg-blue-600","image":"https://images.unsplash.com/photo-1626224583764-f87db24ac4ea?q=80&w=1200&auto=format&fit=crop","secondaryImage":"https://images.unsplash.com/photo-1613918108466-292b78a8ef95?q=80&w=800&auto=format&fit=crop","highlights":"Thảm cao su chống trơn trượt • Đèn LED góc xiên không lóa mắt • Không gian thoáng mát","description":"Khu vực gồm 4 sân cầu lông tiêu chuẩn trong nhà, mặt sàn trải thảm cao su chuyên dụng bám giày và giảm chấn êm ái. Hệ thống đèn chiếu sáng bố trí góc chếch hạn chế chói mắt khi ngửa đầu đón cầu, thông gió tự nhiên không tạo gió xoáy làm bạt cầu.","specs":[{"label":"Quy mô cụm sân","value":"4 sân cầu lông trong nhà"},{"label":"Mặt sàn","value":"Thảm cao su PVC vân chống trượt"},{"label":"Độ cao trần","value":"8m thoáng mát, không gió tạt"},{"label":"Ánh sáng","value":"Đèn LED chống chói mắt người chơi"}],"amenities":["Ghế nghỉ có quạt gió mát mẻ","Dịch vụ căng cước và bá